# Check if the API is running locally on common ports
$ports = @(5100, 5000, 5001, 8080, 7100, 7200)
foreach ($port in $ports) {
    try {
        $r = Invoke-WebRequest -Uri "http://localhost:$port/api/feed" -UseBasicParsing -TimeoutSec 2 -ErrorAction Stop
        Write-Output "Port $port works: $($r.StatusCode)"
        Write-Output $r.Content.Substring(0, [Math]::Min(500, $r.Content.Length))
        break
    } catch {
        # try https
        try {
            $r = Invoke-WebRequest -Uri "https://localhost:$port/api/feed" -UseBasicParsing -TimeoutSec 2 -SkipCertificateCheck -ErrorAction Stop
            Write-Output "Port $port (https) works: $($r.StatusCode)"
            Write-Output $r.Content.Substring(0, [Math]::Min(500, $r.Content.Length))
            break
        } catch {}
    }
}

